begin;
insert into auth.users(id,email,email_confirmed_at) values ('11111111-1111-4111-8111-111111111111','client@marketplace.test',now()),('22222222-2222-4222-8222-222222222222','pro@marketplace.test',now()),('33333333-3333-4333-8333-333333333333','stranger@marketplace.test',now());
insert into market_profiles(id,display_name,role) values ('11111111-1111-4111-8111-111111111111','Client','client'),('22222222-2222-4222-8222-222222222222','Pro','pro'),('33333333-3333-4333-8333-333333333333','Stranger','client');
insert into market_projects(id,client_id,pro_id,title,brief,scope,amount,status) select v,'11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','Test project','Testing booking overlap protection','A valid testing scope',300,'accepted' from unnest(array['aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'::uuid,'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'::uuid]) v;
insert into market_bookings(project_id,starts_at,ends_at) select id,now()+interval '5 days',now()+interval '5 days 2 hours' from market_projects where id in ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
create or replace function pg_temp.assert_true(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create or replace function pg_temp.denied(action text,payload jsonb) returns boolean language plpgsql as $$begin perform public.market_action(action,payload);return false;exception when others then return true;end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select pg_temp.assert_true(pg_temp.denied('message','{"project_id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa","body":"Unauthorized message"}'),'stranger RPC write blocked');
select pg_temp.assert_true(pg_temp.denied('cancel','{"project_id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"}'),'stranger cancellation blocked');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select public.market_action('confirm_booking','{"project_id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"}');
select pg_temp.assert_true(pg_temp.denied('confirm_booking','{"project_id":"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"}'),'overlapping booking rejected');
select public.market_action('cancel_booking','{"project_id":"aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa"}');
select public.market_action('confirm_booking','{"project_id":"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb"}');
select pg_temp.assert_true((select status='confirmed' from market_bookings where project_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),'cancel frees slot');
reset role;
update market_profiles set suspended=true where id='22222222-2222-4222-8222-222222222222';
set local role authenticated;
select pg_temp.assert_true(pg_temp.denied('message','{"project_id":"bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb","body":"Suspended user message"}'),'suspension blocks writes immediately');
select 'PASS: booking conflict, cross-account mutation, suspension tests' as result;
rollback;
